bool hasCycle(struct ListNode* head)//快慢指针判断环形链表
{
    struct ListNode* slow = head;
    struct ListNode* fact = head;
    while (fact && fact->next)
    {
        fact = fact->next->next;
        slow = slow->next;
        if (fact == slow)
        {
            return true;
        }
    }
    return false;
}
//fact每次走一步slow每次走两步，假设他们的距离是n那么每次就是n-1肯定会相遇
//fact每次走一步slow每次走三步，每次就是n-2，那么他们的总长度某一次可能会是-1，假设总长度是c那么，他们的距离就变成了c-1，如果c-1是奇数那么每次n-2还是会变成-1，如果是偶数就可以相遇
